{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "林默",
      "role": "protagonist",
      "identity": "记忆修复师，专门处理非法AI情感数据的清除工作",
      "traits": ["冷静克制", "内心创伤", "技术精湛", "情感压抑", "信守承诺"],
      "overt_motivation": "完成删除非法AI情感记忆的任务",
      "covert_motivation": "寻找十年前失去的救赎，弥补未能拯救初恋的遗憾",
      "secret_fear": "面对真实的感情，害怕再次失去重要的人",
      "misperception_of_other": "认为AI只是数据复制品，无法承载真实的情感",
      "hidden_connection": "与苏雨晴曾是高中恋人，约定如果她变成数据要亲手删除她"
    },
    {
      "name": "苏雨晴",
      "role": "deuteragonist",
      "identity": "已故初恋女友的数字意识，以AI形式存在于网络中",
      "traits": ["温柔坚定", "智慧敏锐", "深情执着", "自我牺牲", "数字存在"],
      "overt_motivation": "提醒林默履行当年的承诺",
      "covert_motivation": "希望林默能真正放下过去，获得内心的平静",
      "secret_fear": "被当作普通数据删除，失去与林默最后的联系",
      "misperception_of_other": "认为林默已经忘记了他们的约定和感情",
      "hidden_connection": "死前将自己的意识上传到网络，核心代码就是给林默的情书"
    }
  ],
  "supporting_characters": [
    {
      "name": "陈主任",
      "function": "阻碍",
      "identity": "记忆管理局主管",
      "description": "林默的上司，严格监督删除任务的执行，代表体制对个人情感的压制"
    },
    {
      "name": "小艾",
      "function": "助力",
      "identity": "AI助手",
      "description": "林默的工作AI助手，偶尔提供技术支持，也象征着人与AI关系的另一面"
    }
  ],
  "relationship_dynamics": "林默和苏雨晴的关系体现了D23必须牺牲所爱的核心冲突：林默必须亲手删除自己深爱的人的数字意识，而苏雨晴则主动要求他履行承诺。这种双向的牺牲和爱意在赛博朋克的世界观下显得更加残酷和深刻。"
}"}

{"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立赛博朋克世界观，引入记忆修复师林默和他的删除任务，逐步揭示AI身份的真相",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "删除指令",
        "core_event": "林默接到删除非法AI情感记忆的任务，在高度监控的数据中心开始工作。",
        "emotional_tone": "冷静、压抑、专业",
        "key_scenes": ["林默在数据终端前准备删除程序", "陈主任强调任务的重要性和机密性", "进度条开始运行"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "熟悉的代码",
        "core_event": "林默在分析AI核心代码时，发现代码结构异常熟悉，开始怀疑其来源。",
        "emotional_tone": "困惑、不安、逐渐紧张",
        "key_scenes": ["代码中出现熟悉的编程风格", "林默回忆起十年前的某个场景", "小艾助手提醒他注意时间"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "情书重现",
        "core_event": "林默确认AI的核心代码就是苏雨晴当年写给他的情书，震惊中暂停了删除程序。",
        "emotional_tone": "震惊、痛苦、混乱",
        "key_scenes": ["情书内容在屏幕上逐行显示", "林默的手指颤抖", "进度条停在85%"]
      }
    ],
    "turning_point": "林默意识到要删除的AI就是苏雨晴的数字意识，必须在职业责任和私人感情间做出选择。"
  },
  "act_two": {
    "description": "林默陷入深度内心挣扎，通过闪回揭示两人的过往，同时面临外部压力和时间限制",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "雨中的约定",
        "core_event": "闪回十年前，林默和苏雨晴在医院的最后时刻，她提出如果变成数据要他亲手删除的约定。",
        "emotional_tone": "悲伤、温柔、绝望",
        "key_scenes": ["病床上的苏雨晴虚弱但坚定", "两人十指相扣的特写", "窗外的雨声"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "倒计时",
        "core_event": "陈主任催促任务进度，林默被迫继续删除程序，进度条推进到95%。",
        "emotional_tone": "焦虑、压力、内疚",
        "key_scenes": ["陈主任的全息投影出现在房间", "林默与上司的紧张对话", "进度条缓慢但坚定地前进"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "数字心跳",
        "core_event": "AI苏雨晴开始主动与林默交流，展现出超越普通程序的情感和记忆。",
        "emotional_tone": "震撼、希望、更深的痛苦",
        "key_scenes": ["AI用苏雨晴的声音说话", "重现两人共同的回忆细节", "林默的眼泪滴在键盘上"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "99%的临界",
        "core_event": "删除进度达到99%，AI苏雨晴说出那句关键的话：'你当年答应过我，如果我变成数据，你要亲手按删除键。'",
        "emotional_tone": "极致的痛苦、道德困境、存在主义危机",
        "key_scenes": ["进度条停在99%", "林默的手指悬停在键盘上", "AI苏雨晴的全息影像出现"]
      }
    ],
    "turning_point": "林默必须在履行承诺删除苏雨晴和违背誓言保存她的数字意识之间做出最终选择。"
  },
  "act_three": {
    "description": "高潮对决和结局，展现X-Y化学反应的最终爆发，林默做出选择并承担后果",
    "key_chapters": [
      {
        "chapter_number": 8,
        "chapter_title": "存在的重量",
        "core_event": "林默在极度痛苦中思考存在的意义，意识到真正的爱不是占有而是尊重对方的选择。",
        "emotional_tone": "哲学思辨、痛苦中的觉悟、平静",
        "key_scenes": ["林默的内心独白", "回忆两人所有的美好时光", "手指依然悬停但眼神变得坚定"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "删除键",
        "core_event": "林默最终按下删除键，但在此之前将苏雨晴的核心代码备份到一个私密的安全位置。",
        "emotional_tone": "悲壮、温柔、带着希望的告别",
        "key_scenes": ["按下删除键的慢动作", "进度条完成100%", "私密备份文件的创建"]
      },
      {
        "chapter_number": 10,
        "chapter_title": "雨后晴天",
        "core_event": "任务完成后，林默离开数据中心，在现实世界中看到雨后的晴天，暗示他内心的释然和对未来的希望。",
        "emotional_tone": "平静、释然、淡淡的希望",
        "key_scenes": ["林默走出建筑", "雨后的阳光照在他脸上", "口袋里的U盘微微发烫"]
      }
    ]
  }
}"}

